from collections import namedtuple

EmailAlternative = namedtuple("EmailAlternative", ["content", "mimetype"])
EmailAttachment = namedtuple("EmailAttachment", ["filename", "content", "mimetype"])

def send_email(subject, message, from_email, recipient_list, attachments=None, alternatives=None):
    if attachments is None:
        attachments = []
    if alternatives is None:
        alternatives = []
    msg = EmailMessage(subject, message, from_email, recipient_list)
    for attachment in attachments:
        msg.attach(EmailAttachment(*attachment))
    for alternative in alternatives:
        msg.attach_alternative(EmailAlternative(*alternative))
    msg.send()
